<?php
declare(strict_types=1);require dirname(__DIR__).'/app/bootstrap.php';
global $db,$auth,$csrf;
$auth->requireAuth();
function back(string $type,string $msg,int $g,string $m):never{$_SESSION['finance_flash']=['type'=>$type,'message'=>$msg];header('Location: /?module=finance&group_id='.$g.'&month='.urlencode($m));exit;}
if($_SERVER['REQUEST_METHOD']!=='POST'||!$auth->can('finance.manage')){http_response_code(403);exit('غير مصرح.');}
$g=(int)($_POST['group_id']??0);$s=(int)($_POST['student_id']??0);$m=(string)($_POST['month']??'');if(!$csrf->verify($_POST['csrf']??null))back('error','انتهت الجلسة.',$g,$m);if(!preg_match('/^\d{4}-\d{2}$/',$m)||!isset($_POST['confirm']))back('error','اختر الشهر وفعّل مربع التأكيد.',$g,$m);
$month=$m.'-01';$desired=max(0,(float)($_POST['paid_amount']??0));$paidAt=(string)($_POST['paid_date']??date('Y-m-d'));if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$paidAt))$paidAt=date('Y-m-d');
try{$db->beginTransaction();$q=$db->prepare("SELECT s.id,s.fee_exempt,COALESCE(s.monthly_fee_override,g.monthly_fee,0) assessed FROM students s JOIN groups g ON g.id=s.group_id WHERE s.id=? AND s.group_id=? AND s.status='active' FOR UPDATE");$q->execute([$s,$g]);$student=$q->fetch();if(!$student)throw new RuntimeException('الطالب غير موجود في المجموعة.');$f=$db->prepare('SELECT id,paid_amount,previous_arrears FROM monthly_fees WHERE student_id=? AND fee_month=? FOR UPDATE');$f->execute([$s,$month]);$fee=$f->fetch();$assessed=(float)$student['assessed'];if(!$fee){$status=$student['fee_exempt']?'exempt':($desired<=0?'unpaid':($desired>=$assessed?'paid':'partial'));$i=$db->prepare('INSERT INTO monthly_fees(student_id,fee_month,base_amount,assessed_amount,previous_arrears,paid_amount,status) VALUES(?,?,?,?,0,?,?)');$i->execute([$s,$month,$assessed,$assessed,$desired,$status]);$feeId=(int)$db->lastInsertId();$old=0;}else{$feeId=(int)$fee['id'];$old=(float)$fee['paid_amount'];if($desired<$old)throw new RuntimeException('تقليل مبلغ مسدد يتطلب عكس دفعة بسبب قواعد التدقيق المالي.');$status=$student['fee_exempt']?'exempt':($desired<=0?'unpaid':($desired>=($assessed+(float)$fee['previous_arrears'])?'paid':'partial'));$u=$db->prepare('UPDATE monthly_fees SET assessed_amount=?,paid_amount=?,status=? WHERE id=?');$u->execute([$assessed,$desired,$status,$feeId]);}$delta=$desired-$old;if($delta>0){$ref='PAY-'.date('YmdHis').'-'.$s.'-'.bin2hex(random_bytes(2));$p=$db->prepare('INSERT INTO payments(student_id,monthly_fee_id,reference_no,amount,method,paid_at,created_by) VALUES(?,?,?,?,?,?,?)');$p->execute([$s,$feeId,$ref,$delta,'manual',$paidAt.' '.date('H:i:s'),(int)$auth->user()['id']]);}$db->commit();$auth->audit((int)$auth->user()['id'],'student_fee_saved',['student_id'=>$s,'month'=>$month,'paid_total'=>$desired]);back('success','تم حفظ رسوم الطالب وتحديث المتبقي والحالة.',$g,$m);}catch(Throwable $e){if($db->inTransaction())$db->rollBack();back('error',$e->getMessage(),$g,$m);}
